{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  return {
    total: issues.length,
    issues: issues.map(i => ({ id: i.id, shortId: i.shortId, project: i.project, status: i.status, count: i.count })),
  };
}"}

{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const eligible = issues.filter(i => i.count >= 100);
  const out = [];
  for (const i of eligible) {
    const { events } = await sdk.sentry.listIssueEvents({ issueId: i.id });
    out.push({
      shortId: i.shortId,
      count: i.count,
      status: i.status,
      eventCount: events.length,
      events: events.map(e => ({ id: e.id, timestamp: e.timestamp, release: e.release })),
    });
  }
  return out;
}"}

{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const eligible = issues.filter(i => i.project === "jobs" && i.count >= 100);
  const rows = [];
  for (const i of eligible) {
    const { events } = await sdk.sentry.listIssueEvents({ issueId: i.id });
    // pick newest by timestamp, regardless of the order the tool returns
    let newest: { timestamp: string; release: string } | null = null;
    for (const e of events) {
      if (!newest || new Date(e.timestamp).getTime() > new Date(newest.timestamp).getTime()) newest = e;
    }
    const release = newest && newest.release ? newest.release : null;
    rows.push({ shortId: i.shortId, count: i.count, status: i.status, latestRelease: release });
  }
  rows.sort((a, b) => b.count - a.count);
  return rows;
}"}
